(function(){'use strict';
/* Ecology Database generator — jahdb-ecology-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-ECLGY-';
var SRC='public';
var RECORD_KIND='ecology record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"title":"Ecosystems","brief":"An ecosystem is a community of living organisms interacting with their physical environment as a functional unit — from a pond to a rainforest.","points":["Biotic components (plants, animals, microbes) interact with abiotic factors (water, light, soil, climate).","Energy flows through ecosystems; matter cycles within them.","Ecosystems have boundaries set by the question asked — a log or a continent.","Emergent properties (productivity, stability) arise from the whole, not the parts."],"examples":["A pond ecosystem: algae, fish, and bacteria cycling nutrients in sunlit water.","A city park as an urban ecosystem shaped by human management."],"history":["Arthur Tansley coined 'ecosystem' in 1935, framing nature as systems.","Eugene Odum's Fundamentals of Ecology (1953) made ecosystems the field's core unit."],"uses":["Environmental management and impact assessment.","Teaching systems thinking about nature.","Designing reserves and restoration projects."],"qa":[["What is the difference between ecosystem and habitat?","A habitat is where an organism lives; an ecosystem is the full community plus its environment."],["How big is an ecosystem?","Any size — ecologists define boundaries to fit the question."],["Are humans part of ecosystems?","Yes — human activity now shapes nearly every ecosystem on Earth."]]},{"title":"Biomes","brief":"Biomes are the planet's major ecological zones — tundra, forest, grassland, desert — defined by climate and dominant vegetation.","points":["Climate (temperature, precipitation) is the primary biome determinant.","Convergent evolution gives similar biomes similar life forms on different continents.","Terrestrial biomes: tundra, taiga, temperate forest, grassland, desert, tropical rainforest.","Aquatic biomes: freshwater, marine, coral reefs, deep ocean."],"examples":["The Sahara and the Mojave: deserts on different continents with similar adaptations.","Coral reefs: the rainforests of the sea in biodiversity."],"history":["Early naturalists mapped vegetation zones; Holdridge (1947) formalized life zones.","Whittaker's biome scheme (1970s) became the textbook standard."],"uses":["Predicting vegetation and wildlife from climate data.","Conservation planning across regions.","Understanding climate-change biome shifts."],"qa":[["How many biomes are there?","Schemes vary from 8 to 14+; the exact count depends on classification."],["Will climate change shift biomes?","Yes — biome boundaries are already moving poleward and upward."],["What biome do I live in?","Check a biome map against your region's temperature and rainfall."]]},{"title":"Food Webs","brief":"A food web maps who eats whom in an ecosystem — the tangled network of feeding relationships that moves energy and nutrients.","points":["Producers (plants) capture solar energy; consumers eat producers or each other; decomposers recycle all.","Real webs are complex networks, not simple linear chains.","Connectance and link density describe web complexity.","Removing or adding species rewires the web, sometimes catastrophically."],"examples":["A kelp forest web: kelp to urchins to sea otters to orcas.","An African savanna web linking grasses, grazers, predators, and scavengers."],"history":["Charles Elton's food pyramids (1927) founded trophic ecology.","Robert Paine's starfish removal experiment (1963) revealed keystone dynamics."],"uses":["Predicting effects of species loss or invasion.","Fisheries management: setting sustainable harvests.","Ecotoxicology: tracing pollutants up the web."],"qa":[["Food chain or food web?","Chains are simplified paths; webs are the real, interconnected network."],["Why do top predators accumulate toxins?","Biomagnification: each trophic level concentrates what the last one ate."],["Can a species be in two trophic levels?","Yes — omnivores feed across levels; webs capture this, chains don't."]]},{"title":"Trophic Levels","brief":"Trophic levels are the feeding positions in an ecosystem — producers, primary consumers, secondary consumers, and so on.","points":["Level 1: producers (autotrophs); level 2: herbivores; level 3+: carnivores and omnivores.","Only ~10% of energy transfers between levels — the rest is lost as heat and metabolism.","This inefficiency limits food chains to 4-5 levels.","Decomposers operate across all levels, recycling the dead."],"examples":["Grass to grasshopper to frog to heron: four trophic levels.","Phytoplankton to krill to fish to seal to orca in the Southern Ocean."],"history":["Lindeman's trophic-dynamic paper (1942) founded ecosystem energetics.","The '10% rule' became ecology's most famous approximation."],"uses":["Fisheries: harvesting lower levels yields more biomass.","Explaining why big predators are rare.","Ecosystem modeling and energy budgets."],"qa":[["Why are there so few top predators?","Energy loss at each level means little remains for the top."],["Is the 10% rule exact?","No — efficiencies range 5-20%; 10% is a useful average."],["Where do humans sit?","Around trophic level 2.2 globally — we eat mostly plants with some meat."]]},{"title":"Energy Flow in Ecosystems","brief":"Energy enters ecosystems as sunlight, flows through food webs, and exits as heat — a one-way trip governed by thermodynamics.","points":["Gross primary productivity: total energy captured; net: what's left after plant respiration.","Energy pyramids always narrow upward — unlike biomass or numbers pyramids, which can invert.","Detrital pathways (dead matter) often move more energy than grazing pathways.","Human appropriation now claims a large share of terrestrial net primary production."],"examples":["A grassland's NPP supporting its herds of grazers.","Deep-sea vents: ecosystems running on chemical energy, not sunlight."],"history":["Lindeman (1942) quantified energy flow through Cedar Bog Lake.","Odum's systems ecology mapped energy with circuit diagrams."],"uses":["Estimating how many people or animals land can support.","Biofuel and biomass energy assessments.","Understanding ecosystem responses to change."],"qa":[["Can energy be recycled in ecosystems?","No — unlike nutrients, energy flows through once and dissipates as heat."],["What is NPP?","Net Primary Productivity: the energy plants make available to the food web."],["Why are oceans less productive than they look?","Most ocean is nutrient-poor desert; productivity concentrates in upwellings and coasts."]]},{"title":"The Carbon Cycle","brief":"The carbon cycle moves carbon between atmosphere, oceans, land, and life — the cycle now being rewired by fossil-fuel burning.","points":["Photosynthesis pulls CO2 into biomass; respiration and decomposition return it.","Oceans hold ~50x the carbon of the atmosphere, exchanging constantly.","Fossil fuels are ancient carbon re-released in a geological instant.","Soils and forests are major carbon sinks — and vulnerable carbon sources."],"examples":["A forest absorbing CO2 by day, releasing some at night through respiration.","Ocean surface waters absorbing a quarter of human CO2 emissions."],"history":["Keeling's Mauna Loa measurements (1958+) revealed the rising CO2 curve.","Carbon-cycle science underpins all climate policy."],"uses":["Climate modeling and carbon budgets.","Forest and soil carbon management.","Carbon markets and offset verification."],"qa":[["How long does CO2 stay in the atmosphere?","Centuries to millennia for a significant fraction — emissions are effectively permanent."],["Do trees solve climate change?","They help, but can't offset fossil emissions alone — and forests can burn."],["What is the ocean's role?","A massive buffer absorbing CO2 and heat — at the cost of acidification."]]},{"title":"The Nitrogen Cycle","brief":"The nitrogen cycle transforms inert atmospheric N2 into living tissue and back — driven almost entirely by microbes.","points":["Nitrogen fixation (bacteria, lightning) converts N2 to usable ammonia.","Nitrification and denitrification move nitrogen through soils and waters.","Humans now fix more nitrogen industrially (fertilizer) than nature does.","Excess nitrogen causes dead zones, algal blooms, and nitrous oxide emissions."],"examples":["Legume root nodules fixing nitrogen for the plant and soil.","Fertilizer runoff creating the Gulf of Mexico dead zone."],"history":["Hellriegel and Wilfarth (1886) proved microbial nitrogen fixation.","Haber-Bosch (1913) industrialized it, transforming agriculture."],"uses":["Fertilizer management in agriculture.","Wastewater treatment design.","Understanding aquatic dead zones."],"qa":[["Why do farmers rotate with legumes?","Legumes' symbiotic bacteria add nitrogen to the soil naturally."],["Is nitrogen pollution as bad as carbon?","Different harms: dead zones, smog, and N2O — a potent greenhouse gas."],["Can we farm without synthetic nitrogen?","Yields would fall sharply; the challenge is using it efficiently."]]},{"title":"The Water Cycle","brief":"The water cycle circulates Earth's water through evaporation, condensation, precipitation, and flow — the basis of all terrestrial life.","points":["Solar energy evaporates water; plants add transpiration (together: evapotranspiration).","Most precipitation falls on oceans; land gets its share via atmospheric transport.","Groundwater stores vast reserves, recharged slowly over decades to millennia.","Humans redirect flows: dams, irrigation, and withdrawals reshape the cycle regionally."],"examples":["The Amazon generating its own rainfall through transpiration.","Ogallala aquifer depletion from a century of irrigation pumping."],"history":["Hutton and early hydrologists described the cycle by the 1700s.","Isotope hydrology (1900s) traced water's actual pathways."],"uses":["Water resource planning and drought management.","Flood prediction and watershed protection.","Agriculture: irrigation depends on cycle knowledge."],"qa":[["Will climate change affect rainfall?","Yes — wet regions generally get wetter, dry regions drier, with more extremes."],["What is a watershed?","The land area draining into a river or lake — the unit of water management."],["Is groundwater renewable?","Slowly — fossil aquifers recharge over millennia; many are being mined."]]},{"title":"Population Dynamics","brief":"Population dynamics studies how populations grow, shrink, and fluctuate — the mathematics of life and death.","points":["Exponential growth when resources are unlimited; logistic growth as limits bite.","Birth, death, immigration, and emigration drive all change.","Density-dependent factors (competition, disease) regulate crowded populations.","Life tables and survivorship curves summarize a species' demographic strategy."],"examples":["A deer population irrupting after predator removal, then crashing.","Bacterial cultures tracing perfect logistic curves in a petri dish."],"history":["Malthus (1798) linked population growth to resource limits.","Lotka and Volterra (1920s) modeled predator-prey cycles mathematically."],"uses":["Wildlife management: setting harvest quotas.","Pest control and invasive species response.","Conservation: minimum viable populations."],"qa":[["What is carrying capacity?","The population an environment can sustain — though it shifts with conditions."],["Why do populations cycle?","Predator-prey lags, disease, and resource pulses drive oscillations."],["Do humans follow logistic growth?","So far technology keeps raising our effective carrying capacity."]]},{"title":"Carrying Capacity","brief":"Carrying capacity is the maximum population an environment can sustain indefinitely — ecology's most debated limit.","points":["Set by the scarcest resource: food, water, space, or nesting sites.","Overshoot degrades the environment, lowering future capacity.","Technology and trade let humans exceed local carrying capacity.","K in the logistic equation is the formal carrying capacity."],"examples":["Reindeer introduced to St. Matthew Island: boom to 6,000, crash to 42.","Fisheries collapsing when harvest exceeds the stock's capacity."],"history":["The concept grew from range management (early 1900s).","Applied to humans controversially since the 1970s."],"uses":["Rangeland and wildlife management.","Fisheries quotas.","Debating human sustainability."],"qa":[["Has Earth reached human carrying capacity?","Debated — it depends on consumption levels and technology, not just headcount."],["Can carrying capacity increase?","Yes through technology and management; it can also collapse through degradation."],["What causes overshoot?","Delayed feedback: populations keep growing after resources peak."]]},{"title":"r/K Selection Theory","brief":"r/K selection describes life-history strategies: many cheap offspring (r) versus few well-provisioned ones (K).","points":["r-strategists: small, fast-breeding, short-lived — weeds, insects, rodents.","K-strategists: large, slow-breeding, long-lived — elephants, oaks, humans.","Disturbed habitats favor r; stable, crowded habitats favor K.","Most species sit on a continuum, not at the extremes."],"examples":["Dandelions producing thousands of wind-blown seeds (r).","An elephant investing 22 months in one calf (K)."],"history":["MacArthur and Wilson (1967) formalized r/K in island biogeography.","Later refined into broader life-history theory."],"uses":["Predicting which species colonize disturbed sites.","Pest management: r-strategists rebound fast.","Conservation: K-strategists recover slowly from losses."],"qa":[["Are humans r or K?","Strongly K-selected — few offspring, heavy investment."],["Which strategy wins after a disaster?","r-strategists colonize first; K-strategists dominate later."],["Is r/K still used?","The terms persist, though modern theory is more nuanced."]]},{"title":"Predator-Prey Dynamics","brief":"Predators and prey are locked in coupled cycles — each population's fate tied to the other's abundance.","points":["More prey grows more predators; more predators shrink prey; fewer prey starve predators.","Classic models predict lagged oscillations between the two.","Refuges, alternative prey, and satiation stabilize real systems.","Predators shape prey behavior, not just numbers — the ecology of fear."],"examples":["Snowshoe hare and lynx: the textbook 10-year cycle.","Wolves changing elk grazing patterns in Yellowstone."],"history":["Lotka-Volterra equations (1920s) first modeled the cycles.","Hudson's Bay fur records provided the classic dataset."],"uses":["Wildlife management and reintroduction.","Biological pest control.","Understanding trophic cascades."],"qa":[["Do predators control prey numbers?","Often, but food, disease, and weather usually co-regulate."],["What is the ecology of fear?","Prey changing behavior to avoid predators — with ecosystem-wide effects."],["Can removing predators backfire?","Yes — mesopredator release and prey irruption are classic outcomes."]]},{"title":"Competition","brief":"Competition — for light, food, space, mates — shapes who lives where and drives evolutionary arms races.","points":["Intraspecific competition (within species) is usually fiercest.","Interspecific competition can exclude species: the competitive exclusion principle.","Resource partitioning lets competitors coexist by dividing the niche.","Competition can be direct (fighting) or indirect (depleting shared resources)."],"examples":["Barnacles partitioning the intertidal zone by desiccation tolerance.","Warblers dividing a spruce tree into feeding zones."],"history":["Gause's Paramecium experiments (1934) demonstrated competitive exclusion.","MacArthur's warblers (1958) showed niche partitioning in action."],"uses":["Explaining species distributions.","Invasion biology: novel competitors disrupt natives.","Agriculture: crop-weed competition."],"qa":[["Can two species occupy the same niche?","Not indefinitely — one outcompetes the other (competitive exclusion)."],["Is competition the main force in nature?","Important, but facilitation and predation matter as much."],["How do similar species coexist?","By partitioning resources, space, or time."]]},{"title":"Mutualism","brief":"Mutualism is cooperation between species where both benefit — one of nature's most productive partnerships.","points":["Obligate mutualists can't survive apart; facultative ones just do better together.","Pollination and seed dispersal are the great plant-animal mutualisms.","Mycorrhizal fungi trade soil nutrients for plant sugars.","Cheaters exploit mutualisms, keeping them evolutionarily dynamic."],"examples":["Bees and flowers: food for pollination service.","Clownfish and anemones: protection traded both ways."],"history":["Early naturalists documented partnerships; modern theory explains their stability.","Mycorrhizal networks ('wood wide web') research exploded in the 2000s."],"uses":["Agriculture: pollinator conservation boosts yields.","Restoration: replanting needs the mutualist partners too.","Understanding ecosystem resilience."],"qa":[["Is mutualism common?","Extremely — most plants depend on mycorrhizae or pollinators."],["Can mutualism turn parasitic?","Yes — the balance shifts with conditions; many partnerships are conditional."],["What threatens pollinators?","Pesticides, habitat loss, disease, and climate mismatch with flowers."]]},{"title":"Parasitism","brief":"Parasites live at the host's expense — a lifestyle so successful that most species on Earth are parasitic.","points":["Ectoparasites live outside (ticks); endoparasites inside (tapeworms).","Parasitoids (many wasps) always kill their host — blurring parasite and predator.","Parasites regulate host populations and shape evolution (Red Queen dynamics).","Complex life cycles move parasites through multiple hosts."],"examples":["A tick feeding on a deer, potentially transmitting Lyme disease.","Parasitoid wasps controlling caterpillar pests in farms."],"history":["Parasitology grew with medicine (1800s).","Ecologists recognized parasites' ecosystem roles in the late 1900s."],"uses":["Medicine and veterinary science.","Biological pest control with parasitoids.","Conservation: parasites are biodiversity too."],"qa":[["Are parasites bad for ecosystems?","No — they're integral, regulating populations and supporting food webs."],["Should conservation save parasites?","Increasingly yes — coextinction threatens host-specific parasites."],["What is the Red Queen hypothesis?","Hosts and parasites must constantly evolve just to stay in place."]]},{"title":"Ecological Niches","brief":"A species' niche is its full ecological role — what it eats, where it lives, when it's active, and what it needs.","points":["The fundamental niche: where a species could live; the realized niche: where it does (after competition).","Hutchinson's n-dimensional hypervolume formalized the concept.","Niche breadth: specialists (narrow) versus generalists (wide).","Empty niches invite invasion or adaptive radiation."],"examples":["A woodpecker's niche: bark insects, tree cavities, daytime foraging.","Raccoons as generalists thriving across human landscapes."],"history":["Grinnell (1917) and Elton (1927) developed early niche concepts.","Hutchinson (1957) gave the modern multidimensional definition."],"uses":["Predicting invasions: matching niches to new regions.","Climate modeling: where can species' niches persist?","Explaining community assembly."],"qa":[["Niche vs habitat?","Habitat is the address; niche is the profession."],["Can niches be empty?","Islands often lack whole guilds — until invaders arrive."],["Do humans have a niche?","We construct ours — arguably the ultimate generalist."]]},{"title":"Keystone Species","brief":"Keystone species have impact far beyond their abundance — remove them and the ecosystem transforms.","points":["Paine's starfish: removing one predator collapsed intertidal diversity.","Sea otters control urchins, protecting kelp forests.","Beavers engineer wetlands; elephants engineer savannas.","Identifying keystones focuses conservation where it matters most."],"examples":["Wolves returning to Yellowstone, reshaping riverside ecology.","Fig trees feeding frugivores through lean seasons in rainforests."],"history":["Paine coined 'keystone species' in 1969.","The concept became conservation's favorite shortcut."],"uses":["Prioritizing species for protection.","Rewilding: restoring keystones to heal ecosystems.","Predicting collapse from single-species loss."],"qa":[["Are keystone species always predators?","No — engineers (beavers), mutualists (figs), and plants qualify."],["How do I identify a keystone?","Removal experiments or modeling — impact disproportionate to biomass."],["Is the concept controversial?","Somewhat — critics note it's context-dependent and hard to prove."]]},{"title":"Trophic Cascades","brief":"Trophic cascades are chain reactions down the food web — predators changing plants by controlling herbivores.","points":["Top-down control: predators suppress herbivores, releasing plants.","Classic: otters to urchins to kelp; wolves to elk to aspen.","Cascades can be behaviorally mediated (fear) as well as consumptive.","Removing top predators often degrades whole ecosystems."],"examples":["Yellowstone: wolves reduced elk browsing, letting willows and beavers return.","Kelp forests collapsing where otters were hunted out."],"history":["Hairston, Smith, and Slobodkin (1960) proposed top-down control.","Estes and Palmisano (1974) documented the otter-urchin-kelp cascade."],"uses":["Predator reintroduction decisions.","Fisheries: overfishing cascades through marine webs.","Understanding ecosystem collapse."],"qa":[["Do trophic cascades always happen?","No — bottom-up forces (nutrients) often dominate; context matters."],["Can humans trigger cascades?","Yes — overfishing and predator eradication are classic triggers."],["How do you prove a cascade?","Long-term data or experiments tracing the full chain."]]},{"title":"Ecological Succession","brief":"Succession is the orderly change of ecological communities over time — from bare ground to mature ecosystem.","points":["Pioneer species colonize bare substrate, modifying it for successors.","Facilitation, tolerance, and inhibition describe species replacement mechanisms.","Climax communities are the stable endpoint — though disturbance resets the clock.","Succession happens after volcanoes, fires, floods, and farm abandonment."],"examples":["Mount St. Helens: lupines pioneering the 1980 blast zone.","An abandoned field becoming forest over decades."],"history":["Cowles (1899) studied dune succession; Clements (1916) formalized the theory.","Gleason's individualistic critique added nuance."],"uses":["Restoration: guiding succession toward desired endpoints.","Forestry: managing successional stages.","Predicting recovery after disturbance."],"qa":[["How long does succession take?","Decades to centuries — grassland fast, old-growth forest slow."],["What is a climax community?","The stable endpoint — though modern ecology sees dynamic equilibria."],["Can succession go backward?","Disturbance resets it; that's retrogression."]]},{"title":"Biodiversity","brief":"Biodiversity is the variety of life — genes, species, and ecosystems — and humanity's life-support system.","points":["Three levels: genetic, species, and ecosystem diversity.","Tropical regions hold most species; hotspots concentrate endemism.","Biodiversity underpins ecosystem services: pollination, clean water, medicine.","Current extinction rates are 100-1000x background — the sixth mass extinction."],"examples":["A single hectare of Amazon forest holding 300+ tree species.","Coral Triangle reefs with unmatched marine diversity."],"history":["The Convention on Biological Diversity (1992) made it policy.","IPBES (2012+) assesses global biodiversity like the IPCC does climate."],"uses":["Conservation prioritization.","Bioprospecting for medicines.","Ecosystem service valuation."],"qa":[["Why does biodiversity matter?","Resilience, services, and options — diverse systems withstand shocks."],["How many species exist?","Described: ~2 million; estimated: 8-10 million, mostly unknown."],["Can we stop the extinction crisis?","Only with habitat protection, restoration, and climate action together."]]},{"title":"Island Biogeography","brief":"Island biogeography explains species richness as a balance between immigration and extinction — with lessons far beyond islands.","points":["Larger islands hold more species; nearer islands get more immigrants.","The equilibrium model predicts richness from area and isolation.","Habitat fragments are 'islands' — the theory guides reserve design.","SLOSS debate: single large or several small reserves?"],"examples":["Darwin's finches diversifying across the Galapagos.","National parks as habitat islands in agricultural seas."],"history":["MacArthur and Wilson's Theory of Island Biogeography (1967).","Became the foundation of fragmentation and reserve science."],"uses":["Designing protected-area networks.","Predicting extinctions from habitat loss.","Understanding island endemism and vulnerability."],"qa":[["Does it apply to non-islands?","Yes — mountaintops, lakes, and habitat fragments follow the same logic."],["Why are island species vulnerable?","Small populations, no predators historically, naive to invaders."],["What is the SLOSS debate?","Whether one large reserve beats several small ones — context decides."]]},{"title":"Metapopulations","brief":"Metapopulations are populations of populations — local groups linked by dispersal, winking in and out across a landscape.","points":["Local extinctions are normal; recolonization rescues the whole.","Connectivity determines persistence more than any single patch.","Source-sink dynamics: productive patches subsidize poor ones.","Corridors and stepping stones maintain the network."],"examples":["Butterflies persisting across a network of meadows.","Frogs recolonizing ponds after local die-offs."],"history":["Levins (1969) formalized the metapopulation concept.","Hanski's butterfly work made it conservation-relevant."],"uses":["Managing fragmented species.","Designing corridor networks.","Reintroduction planning."],"qa":[["Why do local extinctions not doom the species?","Dispersal recolonizes — as long as the network stays connected."],["What breaks a metapopulation?","Losing connectivity: roads, development, or too few patches."],["How many patches are enough?","Models help, but it depends on dispersal ability and patch quality."]]},{"title":"Habitat Fragmentation","brief":"Fragmentation chops continuous habitat into isolated pieces — among the top drivers of biodiversity loss.","points":["Smaller fragments hold fewer species and lose them over time (extinction debt).","Isolation blocks dispersal, gene flow, and recolonization.","Edge effects degrade fragment interiors.","Roads are both barriers and mortality sources."],"examples":["Amazon fragments losing large predators and their prey cascades.","Amphibians unable to cross roads between breeding ponds."],"history":["The Biological Dynamics of Forest Fragments Project (1979+) proved the effects.","Road ecology emerged as a discipline in the 2000s."],"uses":["Land-use planning to minimize fragmentation.","Wildlife crossings and corridor design.","Assessing development impacts."],"qa":[["Is a small fragment worth saving?","Yes — especially connected ones; every patch counts in a network."],["What is extinction debt?","Species doomed by fragmentation but not yet gone — a delayed bill."],["Do wildlife crossings work?","Well-designed ones do, dramatically cutting roadkill and restoring connectivity."]]},{"title":"Fire Ecology","brief":"Fire is a natural architect of many ecosystems — some depend on it, and suppressing it can cause worse fires.","points":["Fire-adapted species need flames: serotinous cones, fire-stimulated germination.","Fire regimes (frequency, intensity, season) shape communities.","Suppression builds fuel loads, leading to catastrophic megafires.","Prescribed burns mimic natural fire safely."],"examples":["Lodgepole pines releasing seeds only after fire.","Australian bush regenerating spectacularly post-fire."],"history":["Early foresters preached suppression; ecologists (1960s+) proved fire's role.","Yellowstone 1988 changed US fire policy."],"uses":["Prescribed burn programs.","Managing the wildland-urban interface.","Restoring fire-dependent ecosystems."],"qa":[["Is fire good or bad?","Depends on the ecosystem — vital in some, devastating in others."],["Why are wildfires getting worse?","Fuel buildup, hotter droughts, and more homes in fire country."],["Should we let fires burn?","Managed wildfire for resource benefit is growing policy — with safeguards."]]},{"title":"Invasive Species","brief":"Invasive species — introduced organisms that spread and harm — are a leading cause of extinctions worldwide.","points":["Invaders escape their natural enemies, outcompeting natives.","Islands suffer most: naive fauna meet novel predators.","Economic costs run to hundreds of billions annually.","Eradication works early; control is forever once established."],"examples":["Brown tree snakes devastating Guam's birds.","Zebra mussels clogging North American waterways."],"history":["Elton's Ecology of Invasions (1958) founded the field.","Global trade keeps accelerating introductions."],"uses":["Biosecurity and ballast-water regulation.","Early detection and rapid response programs.","Island eradications saving endemic species."],"qa":[["Are all introduced species invasive?","No — most fail or integrate quietly; a minority cause harm."],["Can invasions be reversed?","Rarely at scale; prevention and early action are everything."],["Is climate change making it worse?","Yes — shifting climates open new territory for invaders."]]},{"title":"Conservation Biology","brief":"Conservation biology is the crisis discipline — applying ecology to save species and ecosystems from extinction.","points":["Small-population biology: inbreeding, drift, and demographic stochasticity.","Minimum viable populations set recovery targets.","Systematic conservation planning picks reserve networks efficiently.","Values matter: conservation is a normative, mission-driven science."],"examples":["California condors: from 27 birds to 500+ through captive breeding.","The SLOSS-informed design of reserve systems."],"history":["Soulé founded the field in the 1980s as a 'crisis discipline'.","The CBD (1992) gave it international policy teeth."],"uses":["Saving endangered species.","Designing protected areas.","Guiding restoration and rewilding."],"qa":[["Is conservation working?","Yes where applied — many recoveries prove it; the problem is scale."],["What is a minimum viable population?","The size with acceptable extinction risk over a timeframe — often ~thousands."],["Should we prioritize species or ecosystems?","Both — but ecosystem approaches protect more per dollar."]]},{"title":"Restoration Ecology","brief":"Restoration ecology rebuilds damaged ecosystems — replanting, rewetting, and rewilding toward recovery.","points":["Reference ecosystems define the restoration target.","Assisted regeneration: removing barriers and letting nature work.","Active restoration: planting, earthworks, species reintroduction.","Success is measured against ecological function, not just appearance."],"examples":["Kissimmee River: un-channelizing a river to revive wetlands.","Mine sites replanted into functioning forests."],"history":["Bradshaw and Chadwick (1980) launched restoration as science.","The UN Decade on Ecosystem Restoration (2021-2030) scaled ambition."],"uses":["Repairing mines, wetlands, and degraded lands.","Carbon and biodiversity markets funding restoration.","Community livelihoods tied to restored ecosystems."],"qa":[["Can we really restore ecosystems?","Often yes to function; exact historical fidelity is harder."],["How long does restoration take?","Years for grasslands, decades for forests, longer for peatlands."],["Plant trees or let nature regenerate?","Natural regeneration is cheaper and often better — plant where it won't."]]},{"title":"Rewilding","brief":"Rewilding restores natural processes by bringing back missing species and stepping back from management.","points":["Trophic rewilding: restoring top predators and large herbivores.","Pleistocene rewilding debates: proxies for extinct megafauna.","Passive rewilding: simply abandoning land and letting nature return.","Coexistence with people is the central challenge."],"examples":["Wolves in Yellowstone; beavers across Europe.","Oostvaardersplassen: the Dutch rewilding experiment."],"history":["Soulé and Noss (1998) framed rewilding's cores-corridors-carnivores.","European rewilding networks grew in the 2010s."],"uses":["Large-landscape conservation.","Ecotourism economies around wildlife.","Climate resilience through functional ecosystems."],"qa":[["Is rewilding just abandoning land?","No — it's strategic: restoring missing processes, then stepping back."],["What about farmers and safety?","Coexistence tools — compensation, fencing, guard animals — are essential."],["Can cities be rewilded?","Urban rewilding is growing: daylighting streams, wild corridors, native planting."]]},{"title":"Pollination Ecology","brief":"Pollination — mostly by animals — enables most flowering plants and a third of our food.","points":["Bees are the premier pollinators; flies, beetles, birds, and bats matter too.","Specialized partnerships (fig wasps) versus generalist networks.","Pollinator declines threaten crops and wild plants alike.","Habitat, reduced pesticides, and floral diversity support pollinators."],"examples":["Almond orchards renting billions of bees each spring.","Nocturnal moths pollinating night-blooming flowers."],"history":["Sprengel (1793) discovered insect pollination.","Modern pollinator crisis research (2000s+) documented declines."],"uses":["Food security: protecting pollination services.","Farm management: hedgerows and wildflower strips.","Restoration: pollinators first, plants follow."],"qa":[["Will we run out of bees?","Managed honeybees persist; wild pollinators are the crisis."],["Do I need bees for my garden?","Plant diverse natives and skip pesticides — they'll come."],["What is pollination deficit?","When crops get too few visits — a growing yield limiter."]]},{"title":"Decomposition","brief":"Decomposition is nature's recycling — fungi, bacteria, and detritivores returning the dead to the living.","points":["Fungi digest lignin and cellulose; bacteria handle the rest.","Detritivores (earthworms, millipedes) shred and mix organic matter.","Decomposition rate controls nutrient availability and carbon storage.","Cold, dry, or acidic conditions slow it; warm and moist accelerate."],"examples":["A fallen log becoming soil over a decade.","Leaf litter vanishing by spring in a healthy forest."],"history":["Early soil scientists described humus formation (1800s).","Litter-bag experiments quantified decay rates globally."],"uses":["Soil fertility management.","Carbon accounting: soils hold huge carbon stocks.","Forensic ecology: succession on remains."],"qa":[["Why does litter build up in some forests?","Slow decomposition — cold, acidic, or low-nutrient conditions."],["Are decomposers important?","Essential — without them, nutrients lock up and life starves."],["Do earthworms help everywhere?","They're invasive in North American forests, harming native understories."]]},{"title":"Soil Ecology","brief":"Soil is alive — a teaspoon holds more organisms than people on Earth, driving fertility and carbon storage.","points":["Bacteria, fungi, protozoa, nematodes, and arthropods form the soil food web.","Mycorrhizal fungi extend plant roots, trading nutrients for sugars.","Soil organic matter stores carbon and holds water.","Tillage, chemicals, and compaction damage soil life."],"examples":["No-till fields with thriving earthworm populations.","Mycorrhizal networks linking forest trees."],"history":["Soil microbiology grew with microscopy and culturing (1900s).","DNA sequencing (2000s) revealed soil's true diversity."],"uses":["Regenerative agriculture.","Carbon farming and soil carbon markets.","Restoration: rebuilding living soil."],"qa":[["How do I improve my soil?","Add organic matter, minimize tillage, keep it covered and diverse."],["Is soil alive?","Vibrantly — it's among Earth's most biodiverse habitats."],["Can soil fight climate change?","Healthy soils sequester carbon — a meaningful wedge."]]},{"title":"Wetland Ecology","brief":"Wetlands — marshes, swamps, bogs — are biodiversity hotspots and natural water infrastructure.","points":["Waterlogged soils create anaerobic conditions shaping unique communities.","Wetlands filter water, buffer floods, and store carbon (peatlands especially).","Migratory birds depend on wetland networks along flyways.","Over half of the world's wetlands have been drained."],"examples":["The Everglades: river of grass supporting iconic wildlife.","Peat bogs storing more carbon than all vegetation."],"history":["Wetland science grew with waterfowl conservation (1900s).","Ramsar Convention (1971) gave wetlands international protection."],"uses":["Flood control and water purification.","Carbon storage in peatlands.","Fisheries nurseries and bird habitat."],"qa":[["Why protect swamps?","They're among the most productive, valuable ecosystems on Earth."],["Can wetlands be restored?","Yes — rewetting drained land revives function surprisingly fast."],["Do wetlands emit methane?","Yes, naturally — but their carbon storage far outweighs it."]]},{"title":"Coral Reef Ecology","brief":"Coral reefs are the ocean's rainforests — tiny polyps building structures that shelter a quarter of marine species.","points":["Corals are animals hosting symbiotic zooxanthellae algae that power the reef.","Reefs need warm, clear, shallow water — a narrow niche.","Bleaching: stressed corals expel algae, often fatally.","Overfishing removes herbivores, letting algae smother corals."],"examples":["The Great Barrier Reef: 2,300km of reef ecosystem.","A bleaching event turning vibrant coral bone-white."],"history":["Darwin explained atoll formation (1842).","Bleaching science (1980s+) documented the climate threat."],"uses":["Fisheries supporting hundreds of millions.","Coastal protection from storms.","Tourism economies."],"qa":[["Can reefs survive climate change?","Only with rapid emissions cuts plus local protection; some adaptation is occurring."],["What causes bleaching?","Heat stress mainly — even 1-2C above normal for weeks."],["Does sunscreen harm reefs?","Some chemicals do; mineral sunscreens and rash guards are safer."]]},{"title":"Forest Ecology","brief":"Forests cover a third of land, holding most terrestrial biodiversity and carbon — complex systems from canopy to soil.","points":["Vertical structure: canopy, understory, forest floor — each with its community.","Old-growth forests differ profoundly from plantations.","Gap dynamics: falling trees create light gaps driving regeneration.","Mycorrhizal networks connect trees underground."],"examples":["An old-growth Douglas fir forest with 800-year-old trees.","A tropical forest gap filling with pioneer species."],"history":["Forestry science (1800s) met ecology to form forest ecology.","Old-growth research (1980s+) revealed its irreplaceability."],"uses":["Timber, carbon, water, and biodiversity management.","Climate mitigation through forest protection.","Recreation and cultural values."],"qa":[["Plantation or natural forest?","Plantations grow wood; natural forests hold biodiversity — different goals."],["How do forests affect climate?","They store carbon, recycle rainfall, and cool the air."],["Can logged forests recover?","Secondary forests recover much function — but old-growth takes centuries."]]},{"title":"Grassland Ecology","brief":"Grasslands — prairies, steppes, savannas — are disturbance-maintained ecosystems of grasses, grazers, and fire.","points":["Grasses regrow from basal meristems, thriving under grazing and fire.","Large herbivores and fire prevent woody encroachment.","Deep roots build the world's richest soils.","Most temperate grasslands are now farmland — among the least protected biomes."],"examples":["The Serengeti migration: millions of grazers following rains.","Tallgrass prairie with roots reaching 3 meters deep."],"history":["Grassland ecology grew with range science (1900s).","Fire-grazing interaction research reshaped management."],"uses":["Rangeland and livestock management.","Soil carbon in grasslands.","Prairie restoration."],"qa":[["Why burn prairies?","Fire maintains grasses, controls invasives, and recycles nutrients."],["Are grasslands endangered?","Temperate grasslands are among the most converted, least protected biomes."],["Bison or cattle?","Bison shaped these systems; well-managed cattle can mimic some effects."]]},{"title":"Desert Ecology","brief":"Deserts are defined by water scarcity — and life's extraordinary adaptations to it.","points":["Water is the master limiting factor; pulses of rain drive booms.","Adaptations: water storage, nocturnality, deep roots, CAM photosynthesis.","Desert soils host biological crusts fixing nitrogen and preventing erosion.","Deserts are fragile: slow-growing, slow to recover from damage."],"examples":["Saguaro cacti storing hundreds of liters after rains.","Desert wildflower superblooms after wet winters."],"history":["Desert ecology matured with US Southwest research (1900s).","Biocrust research (2000s) revealed the living soil skin."],"uses":["Water management in arid lands.","Solar development sited to avoid sensitive habitat.","Desert restoration and dust control."],"qa":[["Is the desert empty?","Far from it — deserts hold specialized, remarkable biodiversity."],["Why are deserts expanding?","Overgrazing, deforestation, and climate change drive desertification."],["Can deserts be farmed?","With irrigation — but it mines water and salinizes soils."]]},{"title":"Freshwater Ecology","brief":"Freshwater — rivers, lakes, wetlands — holds 10% of species in 1% of Earth's water, and faces intense pressure.","points":["Flow regime defines rivers; stratification defines lakes.","Freshwater biodiversity is disproportionately threatened.","Dams fragment rivers; pollution and withdrawals degrade them.","Environmental flows mimic natural regimes for ecosystem health."],"examples":["Salmon runs linking ocean and river ecosystems.","A lake's thermocline structuring its summer communities."],"history":["Limnology (Forel, 1890s) founded lake science.","River continuum concept (1980) unified stream ecology."],"uses":["Drinking water protection.","Fisheries and dam management.","Wetland and floodplain restoration."],"qa":[["Why are freshwater species so threatened?","Habitat loss, dams, pollution, and invasives concentrated in small habitats."],["Do dams always harm rivers?","They fragment and alter flows; mitigation (fish passage, e-flows) helps partially."],["What is eutrophication?","Nutrient overload causing algal blooms and oxygen crashes."]]},{"title":"Marine Ecology","brief":"Marine ecology studies the 70% of Earth covered by oceans — from sunlit reefs to abyssal plains.","points":["Ocean zones: intertidal to hadal, each with distinct communities.","Upwelling fuels the most productive fisheries.","The deep sea is Earth's largest habitat, barely explored.","Overfishing, warming, and acidification are the triple threat."],"examples":["A kelp forest's vertical zonation.","Whale falls creating deep-sea oases."],"history":["Challenger expedition (1870s) founded oceanography.","Marine ecology matured with SCUBA and submersibles."],"uses":["Fisheries management.","Marine protected areas.","Climate science: oceans drive the system."],"qa":[["How much of the ocean is protected?","A few percent strongly protected — far below scientific targets."],["What is ocean acidification?","CO2 dissolving into seawater, harming shell-builders."],["Can the ocean recover from overfishing?","Yes — well-managed stocks rebound, as many recoveries show."]]},{"title":"Urban Ecology","brief":"Cities are ecosystems too — novel communities of adapters, exploiters, and avoiders in human-built habitat.","points":["Urban adapters (raccoons, pigeons) thrive; avoiders (many specialists) vanish.","Heat islands, fragmentation, and pollution shape urban communities.","Green infrastructure brings nature back: parks, green roofs, daylighted streams.","Cities can be refuges for some threatened species."],"examples":["Peregrine falcons nesting on skyscrapers.","A green roof supporting pollinators downtown."],"history":["Urban ecology emerged in the 1970s-90s (Berlin, New York).","Now mainstream as most humans live in cities."],"uses":["Designing biodiverse cities.","Public health: nature access and cooling.","Stormwater and heat management."],"qa":[["Is city nature 'real' nature?","Yes — novel ecosystems with real ecological processes."],["How do I help urban wildlife?","Native plants, less pesticide, dark skies, and water."],["Do cities harm or help biodiversity?","Both — they destroy habitat but can shelter adaptable species."]]},{"title":"Climate Change and Ecosystems","brief":"Climate change is rearranging ecosystems — shifting ranges, disrupting timing, and pushing systems past tipping points.","points":["Species move poleward and upward tracking their climate niche.","Phenological mismatches: flowers bloom before pollinators emerge.","Tipping points: Amazon dieback, coral loss, permafrost thaw.","Assisted migration and climate-smart conservation are emerging responses."],"examples":["Pikas disappearing from lower-elevation mountaintops.","Coral bleaching events growing more frequent and severe."],"history":["Ecologists documented shifts from the 1990s.","IPCC/IPBES assessments synthesize the global picture."],"uses":["Climate adaptation planning.","Carbon-focused conservation.","Predicting and managing novel ecosystems."],"qa":[["Can ecosystems adapt to climate change?","Some can, slowly — current change is dangerously fast."],["What is assisted migration?","Moving species to future-suitable habitat — controversial but debated."],["Will nature just sort itself out?","Novel ecosystems will emerge, but with great loss — action reduces it."]]},{"title":"The Phosphorus Cycle","brief":"Phosphorus — essential for DNA, bones, and ATP — cycles slowly from rock to life to sediment, with no atmospheric shortcut.","points":["Weathering releases phosphate from rock over geological time.","Plants take up phosphate; animals get it by eating plants.","Unlike carbon and nitrogen, phosphorus has no significant gaseous phase.","Mined phosphate fertilizer is a finite resource — 'peak phosphorus' concerns."],"examples":["Guano islands mined for phosphate fertilizer in the 1800s.","Phosphorus runoff fueling algal blooms in lakes."],"history":["Liebig (1840) identified phosphorus as a limiting nutrient.","Peak-phosphorus debates emerged in the 2000s."],"uses":["Fertilizer management and recycling.","Lake eutrophication control.","Long-term food security planning."],"qa":[["Why is phosphorus special?","No atmospheric cycle means it moves slowly and can truly run out locally."],["Will we run out of phosphorus?","Reserves last decades to centuries; recycling is increasingly urgent."],["Phosphorus vs nitrogen pollution?","Phosphorus drives freshwater blooms; nitrogen drives marine dead zones."]]},{"title":"Ecological Resilience","brief":"Resilience is an ecosystem's capacity to absorb disturbance and reorganize while keeping its essential character.","points":["Engineering resilience: speed of return; ecological resilience: amount of disturbance absorbed.","Diversity, redundancy, and connectivity build resilience.","Regime shifts flip systems to alternative stable states (clear lake to turbid).","Managing for resilience beats managing for constant output."],"examples":["A coral reef recovering from bleaching where herbivores remain.","A lake flipping to algae-dominated after nutrient overload."],"history":["Holling (1973) introduced resilience to ecology.","Regime-shift science (2000s) mapped tipping points."],"uses":["Fisheries and forest management.","Climate adaptation planning.","Restoration targeting resilient states."],"qa":[["Resilience vs stability?","Stability resists change; resilience recovers from it."],["Can resilience be measured?","Proxies exist — recovery rates, diversity, connectivity — but it's partly qualitative."],["Are regime shifts reversible?","Often with hysteresis — returning takes far more effort than the flip did."]]},{"title":"Edge Effects","brief":"Where habitats meet, edges create unique conditions — more light and wind, different species — shaping fragment ecology.","points":["Edges are brighter, drier, and windier than interiors.","Some species thrive at edges; interior specialists decline.","Nest predation and parasitism rise near edges.","The edge-to-interior ratio grows as fragments shrink."],"examples":["Forest-interior birds vanishing from small woodlots.","Invasive plants colonizing along forest edges."],"history":["Edge research grew with fragmentation studies (1980s+).","Informs buffer-zone design around reserves."],"uses":["Reserve design: minimizing edge, maximizing interior.","Corridor width decisions.","Assessing development setbacks."],"qa":[["Are edges good or bad?","Good for edge species, bad for interior specialists — depends on the goal."],["How deep do edge effects penetrate?","Tens to hundreds of meters depending on the factor."],["Can edges be softened?","Yes — planted buffers ease the transition."]]},{"title":"Seed Dispersal Ecology","brief":"Plants can't walk, so they outsource movement — wind, water, and animals carry seeds to new ground.","points":["Anemochory (wind), hydrochory (water), zoochory (animals) are the main modes.","Fleshy fruits bribe animals; hooks and burrs hitchhike.","Dispersal shapes plant distributions and forest regeneration.","Losing dispersers (hunted frugivores) strands the plants."],"examples":["Dandelion clocks riding the wind.","A jay caching acorns, planting tomorrow's oaks."],"history":["Ridley (1930) catalogued dispersal mechanisms.","Modern work links disperser loss to plant declines."],"uses":["Forest restoration: planting needs dispersers too.","Invasion biology: dispersal traits predict spread.","Rewilding: restoring animal dispersers."],"qa":[["How far do seeds travel?","Most fall near the parent; rare long-distance events matter most."],["Do plants need animals to spread?","Many do — the 'empty forest' syndrome follows defaunation."],["What disperses seeds in cities?","Wind, water, pets, and people — novel urban dispersal networks."]]},{"title":"Commensalism","brief":"Commensalism benefits one species while the other is unaffected — nature's free riders.","points":["Epiphytes grow on trees for light without harming them.","Remoras hitch rides on sharks, eating scraps.","Cattle egrets eat insects flushed by grazing herds.","True neutrality is hard to prove — many commensalisms hide small costs or benefits."],"examples":["Orchids perched on rainforest branches.","Barnacles on whales getting transport and feeding currents."],"history":["Documented by early naturalists; debated by modern ecologists.","The category's fuzziness itself became a research topic."],"uses":["Understanding community assembly.","Teaching the symbiosis spectrum.","Epiphyte conservation in logged forests."],"qa":[["Is commensalism real?","Often it's subtle mutualism or parasitism — pure cases are debated."],["Example of human commensalism?","Sparrows nesting on buildings — benefiting, humans unaffected."],["Why does the distinction matter?","It shapes predictions about coevolution and dependence."]]},{"title":"Ecosystem Services","brief":"Ecosystem services are nature's benefits to people — pollination, clean water, flood control — now valued in dollars.","points":["Provisioning (food, timber), regulating (climate, floods), cultural (recreation), supporting (soil formation).","Valuation makes nature's value visible to decision-makers.","Payments for ecosystem services (PES) fund conservation.","Critics warn valuation can't capture all of nature's worth."],"examples":["New York City protecting Catskills watersheds instead of building filtration plants.","Mangroves valued for storm protection."],"history":["Daily's Nature's Services (1997) popularized the framework.","Millennium Ecosystem Assessment (2005) made it global policy."],"uses":["Cost-benefit analysis of conservation.","Natural infrastructure investment.","Corporate sustainability accounting."],"qa":[["Can you put a price on nature?","Partially — valuation is a tool, not a complete ethic."],["Do payments for services work?","Costa Rica's program is the flagship success."],["What's the risk of valuation?","That unpriced nature gets ignored — valuation must complement ethics."]]},{"title":"Wildlife Corridors","brief":"Wildlife corridors reconnect fragmented habitat — strips of habitat letting animals move, mate, and migrate.","points":["Corridors maintain gene flow and recolonization between patches.","Designed for target species' movement needs — width and cover matter.","Road crossings (overpasses, underpasses) are engineered corridors.","Connectivity conservation now works at continental scales."],"examples":["Banff's wildlife overpasses cutting collisions dramatically.","The Yellowstone-to-Yukon corridor initiative."],"history":["Corridor science grew from island biogeography (1980s).","Road-crossing structures proved their worth in the 2000s."],"uses":["Linking protected areas into networks.","Climate adaptation: letting species shift ranges.","Reducing wildlife-vehicle collisions."],"qa":[["Do corridors actually work?","Yes — camera traps and genetics confirm use by target species."],["Could corridors spread disease or invasives?","A debated risk; design and monitoring manage it."],["How wide should a corridor be?","Depends on the species — wider is safer; models guide specifics."]]},{"title":"Protected Areas","brief":"Protected areas — national parks to marine reserves — are conservation's front line, now covering ~17% of land.","points":["IUCN categories range from strict reserves to managed landscapes.","Effectiveness depends on funding, enforcement, and local support.","30x30: the global target of 30% protection by 2030.","Indigenous-managed lands often outperform formal parks."],"examples":["Yellowstone (1872): the first national park.","Costa Rica's park system reversing deforestation."],"history":["The national park idea spread from the US globally.","Marine protection lagged but is accelerating."],"uses":["Biodiversity conservation at scale.","Ecotourism economies.","Climate refugia."],"qa":[["Are parks enough?","No — they must be connected, funded, and complemented by wider conservation."],["Do parks hurt local people?","Fortress conservation did; modern models share benefits and rights."],["What is 30x30?","The global goal to protect 30% of land and sea by 2030."]]},{"title":"Ecological Footprint","brief":"The ecological footprint measures humanity's demand on nature versus what Earth can regenerate — currently about 1.7 Earths.","points":["Counts cropland, grazing, forest, fishing grounds, built land, and carbon uptake.","Overshoot Day marks when yearly demand exceeds yearly regeneration.","Footprints vary hugely: high-income lifestyles demand far more.","Critics debate methodology, but the overshoot signal is robust."],"examples":["Overshoot Day falling in late July in recent years.","A meat-heavy diet roughly doubling food footprint."],"history":["Wackernagel and Rees developed the footprint in the 1990s.","Published annually by the Global Footprint Network."],"uses":["Sustainability communication and education.","National and city footprint accounting.","Personal lifestyle decisions."],"qa":[["How is my footprint calculated?","Online calculators estimate from diet, travel, housing, and consumption."],["Can technology shrink footprints?","Yes — efficiency and clean energy cut the carbon wedge sharply."],["Is 1.7 Earths accurate?","Estimates vary, but all show substantial overshoot."]]},{"title":"Systems Ecology","brief":"Systems ecology treats ecosystems as networks of energy and matter flows — modeling nature with the tools of engineering.","points":["Energy circuit diagrams map flows like electrical schematics.","Emergy accounting values everything in solar-energy equivalents.","Maximum power principle: systems self-organize to maximize useful energy flow.","Models from simple to Earth-system scale inform policy."],"examples":["Odum's Silver Springs study: a full energy budget of a Florida spring.","Global carbon-cycle models guiding climate policy."],"history":["H.T. Odum founded systems ecology in the 1950s-70s.","Influenced Earth-system science and ecological economics."],"uses":["Ecosystem modeling for management.","Energy analysis of economies.","Teaching whole-system thinking."],"qa":[["Is nature really like a circuit?","It's a useful abstraction — flows and storages are real, metaphors have limits."],["What is emergy?","Embodied solar energy — one way to compare disparate flows."],["Does systems ecology still matter?","Its modeling legacy lives on in Earth-system and integrated assessment models."]]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief+' This '+angle+' guide provides comprehensive coverage.',genre:angle,type:RECORD_KIND,content:content,demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-ecology-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('ecology',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();